def binomial(n , k): 
    if(k > n): 
        return 0 
    if(k == 0 or k == n): 
        return 1 
    binomial_coef = 1
    i = min(k, n-k) 
    while(i): 
        binomial_coef = binomial_coef * n 
        n = n-1
        binomial_coef = binomial_coef // i 
        i = i-1
    return binomial_coef

def binomial_coefficient(n, k): 
