def top_k_integers(arr1, arr2, k):
    heap = []
    for num in arr1:
        heapq.heappush(heap, (-arr1.count(num), num))
    for num in arr2:
        heapq.heappush(heap, (-arr2.count(num), num))
    return [heapq.heappop(heap)[1] for _ in range(k)]

