    for i in range(n):
        for j in range(i+1, n):
            if (arr[j] - arr[i]) == 1:
                result = max(result, j-i+1)
    return result

def max_len(arr):
    if (len(arr) == 0):
        return 0
    dp = [1 for i in range(len(arr))]
    for i in range(1, len(arr)):
        for j in range(0, i):
            if abs(arr[i] - arr[j]) == 1:
                dp[i] = max(dp[i], 1 + dp[j])
    return max(dp)

def findMaxLengthSubsequence(arr):
  n = len(arr)
  d = [[0 for i in range(n)] for j in range(2)]
  d[0][0] = 1
  for i in range(1, n):
    d[1][i] = 1
    for j in range(i):
      if (abs(arr[i] - arr[j]) == 1):
        d[1][i] = max(d[1][i], d[0][j] + 1)
    d[0][i] = max(d[0][i - 1], d[1][i])
  return d[0][n - 1]

def maxSubseqLen(arr, n):
    first = 1
    second = 0
    for i in range(1, n):
        if (arr[i] - arr[i - 1] == 1):
            first = max(first, second + 1)
        second = max(second, first + 1)
    return first

def array_diff_subsequence(A):
  n = len(A)
  pre = [0 for i in range(n)]
  suf = [0 for i in range(n)]
  pre[0] = A[0]
  for i in range(1,n):
    pre[i] = max(pre[i-1], A[i])
  suf[n-1] = A[n-1]
  for i in range(n-2,-1,-1):
    suf[i] = max(suf[i+1], A[i])
  max_length = 0
  for i in range(1,n-1):
    if (pre[i-1] >= A[i] and suf[i+1] <= A[i]) or (pre[i+1] <= A[i] and suf[i-1] >= A[i]):
      max_length = max(max_length, (suf[i] - A[i]) + (A[i] - pre[i]))
  return max_length

def max_len_subseq(arr):
    n = len(arr)
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if (arr[i] - 1 == arr[j] or arr[i] + 1 == arr[j]) and (dp[i] < dp[j] + 1):
                dp[i] = dp[j] + 1
    return max(dp)

def max_length_subseq(arr):
    n = len(arr)
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if (arr[i] - arr[j]) * (arr[i] - arr[j]) <= 1:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def max_subseq_len(arr):
    if len(arr) == 0:
        return 0
    dp = [1] * len(arr)
    for i in range(1, len(arr)):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= 1:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def find_max_seq(arr):
    if len(arr)==0:
        return 0
    dp = [1 for _ in arr]
    for i in range(1,len(arr)):
        for j in range(i):
            if abs(arr[i]-arr[j])<=1:
                dp[i] = max(dp[i], dp[j]+1)
    return max(dp)
